import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String w1 = sc.next();
        String w2 = sc.next();
        int cmp = w1.compareTo(w2);
        if(cmp < 0) {
            System.out.println("first");
        } else if(cmp > 0) {
            System.out.println("second");
        } else {
            System.out.println("equal");
        }
    }
}

import java.util.Scanner;

public class Main {
