import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        String[] parts = line.split(" ");
        String initials = "";
        for(int i = 0; i < parts.length; i++) {
            initials = initials + parts[i].charAt(0);
        }
        System.out.println(initials);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String plate = sc.next();
        boolean ok = plate.length() == 6
            && Character.isUpperCase(plate.charAt(0))
            && Character.isUpperCase(plate.charAt(1))
            && Character.isDigit(plate.charAt(2))
            && Character.isDigit(plate.charAt(3))
            && Character.isDigit(plate.charAt(4))
            && Character.isDigit(plate.charAt(5));
        if(ok) {
            System.out.println("valid");
        } else {
            System.out.println("invalid");
        }
    }
}
